import type { Course } from '../../curriculum'
import type { Question } from '../../questions'
import { canonicalCourses } from '../../taxonomy/canonicalCourses'

const openStaxChem = 'https://openstax.org/books/chemistry-2e/pages/'
type Draft = Pick<Course, 'objectives' | 'sections' | 'trap' | 'recall' | 'answer' | 'source'> & Partial<Pick<Course, 'learning' | 'glossary' | 'caseStudy'>>
const meta = new Map(canonicalCourses.filter(item => item.subject === 'Chimie').map(item => [item.id, item]))
const build = (id: string, draft: Draft): Course => {
  const canonical = meta.get(id)
  if (!canonical) throw new Error(`Chapitre canonique de chimie introuvable : ${id}`)
  return {
    id, title: canonical.title, category: canonical.subject, tag: canonical.module, minutes: 12,
    structure: null, objectives: draft.objectives, sections: draft.sections, trap: draft.trap,
    recall: draft.recall, answer: draft.answer, source: draft.source,
    sources: [{ label: draft.source.includes('organic-chemistry') ? 'OpenStax · Organic Chemistry' : 'OpenStax · Chemistry 2e', url: draft.source }],
    prerequisites: ['Quantité de matière et unités SI', 'Écriture d’une réaction chimique équilibrée'],
    review: { status: 'unreviewed', updatedAt: '2026-09-23', sourcesUpdatedAt: '2026-09-23' },
    ...(draft.learning ? { learning: draft.learning } : {}),
    ...(draft.glossary ? { glossary: draft.glossary } : {}),
    ...(draft.caseStudy ? { caseStudy: draft.caseStudy } : {})
  }
}
const s = (title: string, text: string, bullets?: string[]) => ({ title, text, ...(bullets ? { bullets } : {}) })

