    learning: { formula: { label: 'Loi de vitesse empirique', expression: 'v = k[A]ᵐ[B]ⁿ', explanation: 'Les exposants sont déterminés expérimentalement ; l’ordre global vaut m+n.' }, comparison: { headers: ['Modification', 'Effet cinétique fréquent', 'Change K à T constante ?'], rows: [['Concentration', 'Change v selon la loi de vitesse', 'Non'], ['Catalyseur', 'Augmente les vitesses directe et inverse', 'Non'], ['Température', 'Change k et souvent v', 'Oui, peut changer K']] }, example: { prompt: 'Doubler [A] quadruple v', steps: ['Écrire 4 = 2ᵐ', 'Comparer les puissances', 'm = 2'], result: 'La réaction est d’ordre 2 par rapport à A.' }, errors: [{ title: 'Confondre cinétique et thermodynamique', detail: 'La vitesse dit combien de temps prend une transformation ; K compare les états à l’équilibre.' }] }
